window.NOTES={"version":70,"chapters":[{"number":1,"title":"信息技术与计算机文化","summary":"计算机发展、信息表示、硬件、软件与计算机系统的基础概念。","sections":[{"id":"1.1","title":"信息与信息技术"},{"id":"1.2","title":"计算机技术概论"},{"id":"1.3","title":"计算机中信息的表示"},{"id":"1.4","title":"计算机系统"},{"id":"1.5","title":"微型计算机系统"}]},{"number":2,"title":"Windows 10 操作系统","summary":"操作系统特征、Windows界面、文件管理、系统设置与维护。","sections":[{"id":"2.1","title":"操作系统概述"},{"id":"2.2","title":"Windows 10 基础"},{"id":"2.3","title":"文件和文件夹管理"},{"id":"2.4","title":"控制面板"},{"id":"2.5","title":"Windows 10 的系统维护"},{"id":"2.6","title":"Windows 10 的实用工具"}]},{"number":3,"title":"字处理软件 Word 2016","summary":"文档编辑、格式排版、表格、图文混排与长文档功能。","sections":[{"id":"3.1","title":"使用 Office 2016 应用程序"},{"id":"3.2","title":"Word 2016 的基本操作"},{"id":"3.3","title":"文档格式化与排版"},{"id":"3.4","title":"表格制作"},{"id":"3.5","title":"图文混排"},{"id":"3.6","title":"文档的保护与打印"},{"id":"3.7","title":"Word 2016 的高级应用"}]},{"number":4,"title":"电子表格系统 Excel 2016","summary":"工作表操作、公式与函数、格式化、数据处理和图表。","sections":[{"id":"4.1","title":"Excel 2016 概述"},{"id":"4.2","title":"Excel 2016 的基本操作"},{"id":"4.3","title":"Excel 公式与函数"},{"id":"4.4","title":"格式化工作表"},{"id":"4.5","title":"数据处理"},{"id":"4.6","title":"使用图表"}]},{"number":5,"title":"演示文稿软件 PowerPoint 2016","summary":"幻灯片组织、外观、动画、切换与放映设置。","sections":[{"id":"5.1","title":"PowerPoint 2016 基础"},{"id":"5.2","title":"幻灯片页面设计"},{"id":"5.3","title":"幻灯片页面外观的修饰"},{"id":"5.4","title":"动画效果和动作设置"},{"id":"5.5","title":"播放和打印演示文稿"},{"id":"5.6","title":"演示文稿的其他功能"}]},{"number":6,"title":"计算机网络及网页制作","summary":"网络结构、Internet应用、HTML、网页与信息检索。","sections":[{"id":"6.1","title":"计算机网络概述"},{"id":"6.2","title":"计算机网络系统"},{"id":"6.3","title":"Internet 基础和应用"},{"id":"6.4","title":"网页、网页制作及 HTML 简介"},{"id":"6.5","title":"信息检索"}]},{"number":7,"title":"数字多媒体技术基础","summary":"多媒体特征、媒体元素、图像格式、颜色和视频。","sections":[{"id":"7.1","title":"数字多媒体技术概述"},{"id":"7.2","title":"数字多媒体系统组成及常用软件"},{"id":"7.3","title":"常用多媒体制作软件"}]},{"number":8,"title":"信息安全","summary":"安全属性、恶意软件、防火墙、密码技术和信息伦理。","sections":[{"id":"8.1","title":"信息安全概述"},{"id":"8.2","title":"计算机病毒"},{"id":"8.3","title":"防火墙"},{"id":"8.4","title":"Windows 10 操作系统安全"},{"id":"8.5","title":"信息伦理"}]},{"number":9,"title":"信息技术前沿","summary":"虚拟现实、云计算、物联网、区块链与人工智能。","sections":[{"id":"9.1","title":"虚拟现实和增强现实"},{"id":"9.2","title":"云计算和高性能计算"},{"id":"9.3","title":"物联网技术"},{"id":"9.4","title":"大数据技术"},{"id":"9.5","title":"区块链技术"},{"id":"9.6","title":"人工智能"},{"id":"9.7","title":"量子信息"},{"id":"9.8","title":"元宇宙"}]},{"number":10,"title":"数据库技术基础","summary":"关系数据库、数据库管理系统、关系运算、SQL与NoSQL。","sections":[{"id":"10.1","title":"数据库技术基础"},{"id":"10.2","title":"数据库管理系统"},{"id":"10.3","title":"数据库设计与 NoSQL"}]},{"number":11,"title":"计算思维","summary":"计算思维、算法表示、算法特征和基本控制结构。","sections":[{"id":"11.1","title":"计算思维"},{"id":"11.2","title":"计算思维与算法"},{"id":"11.3","title":"算法的控制结构"},{"id":"11.4","title":"面向对象程序设计"},{"id":"11.5","title":"基础算法设计思想"}]}],"notes":[{"q":29,"chapter":9,"section":"9.1","type":"多选","topic":"虚拟现实","title":"虚拟现实与增强现实：环境、交互和判断边界","trigger":"真题从应用、VR与AR区别和特征选择考查虚拟现实。","conclusion":"VR主要呈现可交互的虚拟环境；AR在现实环境中叠加并关联数字内容。教材常用沉浸性、交互性、构想性概括VR，判断具体应用仍需检查实现条件。","points":["沉浸性让用户产生置身环境的感受，交互性让系统根据动作反馈。","普通3D游戏或三维电影不能仅凭“3D”自动认定为VR。","美容预览可能是图像处理或增强现实，需看是否建立可交互虚拟环境。","VR以虚拟环境为主；AR把数字信息叠加到现实环境并与之关联。两者都可能具有交互和临场体验，不能笼统断言AR总比VR更沉浸或更独立。","教材常用“三I”框架：Immersion沉浸性、Interaction交互性、Imagination构想性（也译想象性）。构想性强调借助虚拟环境探索、设计和表达设想；这是常用教学框架，不是所有行业文档都必须采用的唯一特征表。","一次VR交互可这样理解：系统建立虚拟场景，跟踪头部或手部等输入，再实时更新画面、声音或其他反馈。视觉、听觉等感觉通道配合体现多感知性，不要求每套系统都具备全部感官通道。头显是常见显示设备，控制器和跟踪设备提供交互；仅戴上显示设备或播放立体影片，不足以证明整套交互条件。","AR先取得现实环境或观察者位置，再把数字标记、模型等与现实对象对准，随视角变化更新。例如维修时把部件名称和操作位置叠加在实际机器上；环境仍是现实机器，数字层提供辅助信息。位置跟踪或对准出错会让标记漂移。","经典AR研究用“虚实结合、实时交互、三维注册（空间对准）”描述系统。普通照片后期合成、电影特效或任意贴在画面角落的二维字幕，不因此自动满足这一语境。AR并非低配VR；选用哪种取决于是否需要保留真实环境。","旧题条件边界：2020年第29题配套答案对游戏和美容预览采用宽泛VR归类，题面不足以确认具体实现；2021年第29题配套答案中的沉浸性比较不能推广成AR总比VR更有临场感。保留原题入口，按题面语境判断，技术结论仍以上述环境与交互条件为准。"],"boundary":"判断VR不能只看画面是否立体，还要检查沉浸、交互和环境生成条件。","id":"merged-18","sources":[{"year":2020,"q":29,"type":"多选"},{"year":2026,"q":29,"type":"多选"},{"year":2021,"q":29,"type":"多选","page":5}],"keys":["2020-29","2026-29","2021-29"],"related":[{"id":"y2026q4","label":"多媒体强调集成、交互与实时处理","reason":"VR中的多感知、交互和实时反馈建立在多媒体能力上，但判断VR还须确认可交互的虚拟环境。"},{"id":"y2024q20","label":"沉浸与互操作不会自动消除隐私风险","reason":"沉浸体验需要感知用户动作和环境，进一步查看这些数据采集为何带来隐私与治理问题。"}],"pointGroups":[{"title":"VR的教学框架与体验过程","indices":[4,0,5]},{"title":"AR的现实环境与数字层","indices":[3,6,7]},{"title":"应用判断与旧题条件","indices":[1,2,8]}],"pointPresentation":{"0":{"title":"沉浸与反馈","navigationLabel":"沉浸与反馈"},"1":{"title":"3D不自动等于VR","navigationLabel":"3D不自动等于VR"},"2":{"title":"美容预览要看实现","navigationLabel":"美容预览要看实现"},"3":{"title":"VR与AR的环境区别","navigationLabel":"VR与AR的环境区别"},"4":{"title":"三I与构想性","navigationLabel":"三I与构想性"},"5":{"title":"VR设备与反馈过程","navigationLabel":"VR设备与反馈过程"},"6":{"title":"AR空间对准与更新","navigationLabel":"AR空间对准与更新"},"7":{"title":"经典AR定义的范围","navigationLabel":"经典AR定义的范围"},"8":{"title":"旧题配套答案的条件","navigationLabel":"旧题配套答案的条件"}},"searchAliases":["增强现实 AR","虚拟现实 VR","构想性 三I","空间注册"]},{"q":20,"chapter":9,"section":"9.2","type":"单选","topic":"云计算","title":"云计算的服务方式与高性能计算的并行求解","trigger":"真题从临时取得算力存储、云特征、远程租用和IaaS/PaaS/SaaS考查云计算。","conclusion":"云计算关注资源如何按需提供和管理，HPC关注如何用高性能系统并行求解复杂任务。二者可以结合；增加资源不保证任务按节点数等比例加速。","points":["IaaS提供计算、存储、网络等基础资源，用户可管理操作系统和应用；PaaS提供开发运行平台，用户部署自己的应用；SaaS直接提供现成应用，用户主要使用和配置应用。","资源池把资源统一组织并按需分配，快速弹性使资源随负载增减。例如报名高峰增加计算资源，峰后释放；可度量则让双方能统计和管理使用量。","典型特征是按需自助、广泛网络访问、资源池化、快速弹性、可度量服务。仅远程控制一台配置固定的电脑，并不能由“远程”二字推出它具备这些特征。","公有云面向公众开放使用；私有云供一个组织专用。私有云可由本组织或第三方管理，可部署在组织内部或外部，关键是专用范围。","人少、场地小、数据增长快时可考虑云存储，按需求扩容并减少自建机房投入；仍须评估持续费用、网络依赖、备份、权限和服务商责任，不能理解为无需管理或必然最便宜。","识别云服务可沿一次使用过程：用户通过服务接口申请资源，资源池分配计算或存储能力，负载改变时扩缩容，用量可被监测，任务结束后释放不再需要的资源。可度量不等于所有服务必须采用同一种计费方式。","服务模型和部署模型是两条分类轴：IaaS/PaaS/SaaS区分供需双方管理什么，公有/私有等区分谁使用及如何组织。混合云把两个或多个保持独立的云基础设施通过技术结合以支持数据或应用迁移；不能只凭“既有电脑又有互联网”认定混合云。","高性能计算HPC利用高性能计算系统和并行计算资源，处理大规模或高复杂度的计算任务，例如气象模拟、材料计算。超级计算机或计算集群是常见实现；“高性能”描述计算能力和任务要求，不按机箱体积定义。","并行求解先分析任务依赖，把能同时执行的部分分给多个处理单元，再交换数据并合并结果。必须顺序执行的部分，以及通信、同步和调度开销，会限制加速；多个节点共同工作不等于每一步都能并行。","例如同一任务单节点耗时100秒，其中20秒不能并行，另外80秒理想均分给4个节点且忽略开销，则需20＋80÷4＝40秒，加速2.5倍，不是4倍。串行部分不变时，继续加节点也不能消除这20秒；实际耗时还可能受通信和负载不均衡影响。","云与HPC不是互斥选项：云平台可以按需分配HPC所用资源，机构也可以在自建集群上运行HPC任务。先问“资源怎样获得”，再问“计算任务怎样组织”；普通云应用不必是HPC，HPC也不必通过公有云提供。","2022年第20题的配套答案把第三方承载管理作为辨析线索，但NIST定义允许私有云由第三方管理并部署在组织外。判断私有云应确认是否供单一组织专用；只知道托管方，条件仍不充分。"],"boundary":"云服务不是天然更便宜或绝对安全，安全、容量和费用仍需共同治理。","id":"y2026q39","sources":[{"year":2023,"q":20,"type":"单选"},{"year":2025,"q":17,"type":"单选"},{"year":2025,"q":45,"type":"填空"},{"year":2026,"q":39,"type":"判断"},{"year":2022,"q":20,"type":"单选"},{"year":2021,"q":60,"type":"分析","page":10}],"keys":["2023-20","2025-17","2025-45","2026-39","2022-20","2021-60"],"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"物联网可把集中存储分析交给云，也可在边缘处理；云服务并不意味着全部设备数据都必须上云。"},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"云可按需提供计算资源，但实际算力表现仍受网络、存储、软件栈和调度影响。"}],"pointGroups":[{"title":"先识别按需服务与资源池","indices":[2,5,1]},{"title":"服务层级、部署范围与责任","indices":[0,3,6,4,11]},{"title":"HPC：任务如何并行求解","indices":[7,8,9,10]}],"comparison":{"headers":["服务模型","使用者的典型工作","辨认线索"],"rows":[["IaaS","配置虚拟机并安装系统、应用","租用基础计算资源"],["PaaS","提交代码、部署和管理自己的应用","使用现成运行平台"],["SaaS","直接登录并使用在线应用","使用现成软件功能"]]},"pointPresentation":{"0":{"title":"IaaS、PaaS、SaaS管理边界","navigationLabel":"IaaS、PaaS、SaaS管理边界"},"1":{"title":"资源池、弹性与计量","navigationLabel":"资源池、弹性与计量"},"2":{"title":"云的五项识别条件","navigationLabel":"云的五项识别条件"},"3":{"title":"公有云和私有云","navigationLabel":"公有云和私有云"},"4":{"title":"选用云存储的取舍","navigationLabel":"选用云存储的取舍"},"5":{"title":"申请、使用与释放资源","navigationLabel":"申请、使用与释放资源"},"6":{"title":"服务模型与部署模型","navigationLabel":"服务模型与部署模型"},"7":{"title":"HPC的任务与系统","navigationLabel":"HPC的任务与系统"},"8":{"title":"并行任务的拆分和限制","navigationLabel":"并行任务的拆分和限制"},"9":{"title":"100秒任务的完整计算","navigationLabel":"100秒任务的完整计算"},"10":{"title":"云计算与HPC可结合","navigationLabel":"云计算与HPC可结合"},"11":{"title":"私有云托管的旧题边界","navigationLabel":"私有云托管的旧题边界"}},"searchAliases":["高性能计算 HPC","超级计算机 集群 并行计算","混合云","IaaS PaaS SaaS"]},{"q":30,"chapter":9,"section":"9.3","type":"多选","topic":"物联网","title":"物联网的感知、连接与数据处理","trigger":"真题从三层架构、识别定位、云平台、应用识别和海量数据处理考查物联网。","conclusion":"物联网围绕物体建立感知、连接、数据交换和智能服务；传感器、RFID和定位技术采集状态，网络与云边平台完成传输处理。","points":["大量联网设备是大数据的重要来源。","网络层传输数据，应用层形成面向场景的服务。","边缘计算可降低延迟和带宽压力，云平台适合集中存储、分析和管理。","RFID利用射频信号识别标签，是物联网常见感知技术；不同类型标签的供电、距离和读写能力不同。","传感器把温度、压力、光等被测量转换为可用信号，属于物联网感知环节；采集、联网与应用分析是不同分工。","常用三层架构的完整名称：感知层、网络层、应用层。传感器/RFID归感知层，传输归网络层，具体服务归应用层。","以温室为例：传感器采到32℃，网络把数值送到控制程序；程序按设定阈值判断过热，再发送开风扇指令。传感器负责取得状态，网络负责传送，应用负责规则与服务，执行器把控制结果作用到环境。","三层架构是本节用于分清职责的常用教学划分，不是唯一标准分层。ITU的参考模型还单列服务与应用支撑，并设置管理、安全等跨层能力；不要把物联网三层与TCP/IP协议层逐层等同。","采到数值、成功上传、产生控制命令、执行器实际动作，是不同状态。断网时平台可能只看到旧样本；发出“开风扇”命令也不代表设备已执行，需按应用条件核对送达与执行结果。","云平台便于集中处理大量设备数据，但并非每项物联网服务都必须依托云。2026年第40题配套答案采用云与物联网结合的教材概括；不能据此排除局域网或边缘设备上的本地控制。","智慧城市或智能制造中，识别与感知取得现实状态，网络连接传送数据，应用按规则或模型形成服务；简单阈值控制也可以形成物联网应用，不必使用AI。蜂窝移动通信是一种连接选择，移动网络与Wi-Fi热点的区别见\u003ca href=\"./chapter6.html#syllabus-mobile-communication\">第6章移动通信主入口\u003c/a>。","识别、测量和定位回答不同问题：RFID读取标签标识等数据，温度传感器测量温度，GPS（全球定位系统）等提供位置。识别或定位结果只有结合连接与应用流程，才形成完整物联网服务；物联网可借助互联网等现有网络连接物体，不是与互联网互不关联的全新网络，也不等于Internet本身。"],"boundary":"物联网强调物体通过网络交换数据并形成应用；设备可经网关联网，也可在局域网内完成部分服务，不要求每个设备都直接接入公网或把全部数据上传云端。","id":"merged-19","sources":[{"year":2023,"q":30,"type":"多选"},{"year":2024,"q":50,"type":"填空"},{"year":2026,"q":19,"type":"单选"},{"year":2026,"q":40,"type":"判断"},{"year":2022,"q":40,"type":"判断"},{"year":2021,"q":40,"type":"填空","page":6}],"keys":["2023-30","2024-50","2026-19","2026-40","2022-40","2021-40"],"related":[{"id":"y2026q39","label":"云计算强调按需资源、资源池化、弹性与分层服务","reason":"云平台可承接集中存储和分析，服务模型与弹性说明这些资源如何按需提供和管理。"},{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"大量传感器和联网设备可持续产生多来源数据，但是否体现大数据特征还要看规模、速度和类型。"},{"id":"merged-13","label":"TCP/IP四层模型与OSI七层模型的对应关系","reason":"物联网三层按感知、传输和服务分工；TCP/IP分层按通信协议职责划分，两个模型不能只按层名机械对应。"}],"pointGroups":[{"title":"感知到应用的职责","indices":[5,4,3,11,1,6]},{"title":"数据闭环及连接失败","indices":[8,10]},{"title":"三层、云边与数据规模的边界","indices":[7,2,9,0]}],"pointPresentation":{"0":{"title":"设备数据与大数据","navigationLabel":"设备数据与大数据"},"1":{"title":"网络层与应用层","navigationLabel":"网络层与应用层"},"2":{"title":"边缘和云的分工","navigationLabel":"边缘和云的分工"},"3":{"title":"RFID识别","navigationLabel":"RFID识别"},"4":{"title":"传感器采集","navigationLabel":"传感器采集"},"5":{"title":"三层完整名称","navigationLabel":"三层完整名称"},"6":{"title":"温室控制的完整链","navigationLabel":"温室控制的完整链"},"7":{"title":"教学三层与标准分层","navigationLabel":"教学三层与标准分层"},"8":{"title":"采样、上传、命令、执行","navigationLabel":"采样、上传、命令、执行"},"9":{"title":"物联网不必全部上云","navigationLabel":"物联网不必全部上云"},"10":{"title":"应用场景与连接选择","navigationLabel":"应用场景与连接选择"},"11":{"title":"RFID、传感器与GPS的分工","navigationLabel":"RFID、传感器与GPS的分工"}},"searchAliases":["执行器 传感器","感知层 网络层 应用层","物联网断网"]},{"q":50,"chapter":9,"section":"9.4","type":"填空","topic":"大数据特征","title":"大数据的规模、速度、多样性与价值密度要按材料判断","trigger":"真题从多种数据格式和海量视频中的少量有效片段考查大数据特征。","conclusion":"文本、图像、音视频和日志并存体现多样性Variety；海量数据中有用信息占比较低体现低价值密度。","points":["Volume强调规模大，Velocity强调产生和处理速度快。","Variety强调结构化、半结构化和非结构化数据并存。","价值密度低不等于最终提取出的信息没有价值。","广告推荐、交通分析和城市运行分析可利用大规模多来源数据；单次扫描条形码只是识别行为，不能仅凭“有码”认定为大数据。","大数据不只意味着“文件很大”。当规模、速度、多样性等使常规方法难以经济有效地完成存储与分析时，需要相应可扩展处理架构；没有对所有系统都适用的固定容量门槛。","可沿采集、存储、处理分析、呈现应用理解流程。例如交通传感器和车辆轨迹进入系统，先校验时间和异常值，再按路段聚合并分析拥堵，最终用于交通组织。数据量大不会自动完成清洗、分析或产生有效决策。","教材和资料有4V、5V等不同概括；Veracity强调可信度和数据质量。按材料识别其强调的特征，比凑齐固定字母数更重要；缺失、偏差和重复数据仍可能使分析结果失真。","技术关系要按职责看：物联网可以提供数据，云可提供弹性资源，HPC可承担复杂并行计算，AI可执行识别或预测。它们可以配合，但大数据系统不必全部同时使用这些技术。"],"boundary":"同一材料可能同时具有多个V；题目突出“种类/格式”时判断多样性，突出“有用占比”时判断价值密度。","id":"y2025q18","sources":[{"year":2023,"q":50,"type":"填空"},{"year":2025,"q":18,"type":"单选"},{"year":2022,"q":30,"type":"多选"}],"keys":["2023-50","2025-18","2022-30"],"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"从传感器、RFID和联网设备理解大数据的一类来源，也辨认单次识别为何不足以说明大数据。"},{"id":"y2025q40","label":"推荐系统发现相关性不等于证明因果关系","reason":"从多来源数据提取有用模式不代表获得因果解释，规模扩大也不能自动消除偏差。"},{"id":"y2026q12","label":"NoSQL按数据模型与访问需求选型","reason":"多样的数据与查询需求会影响数据库选型，不能仅因数据量大就默认使用某一种NoSQL产品。"}],"pointGroups":[{"title":"概念与材料中的特征","indices":[4,0,1,2,6]},{"title":"从数据到应用","indices":[5,3,7]}],"pointPresentation":{"0":{"title":"规模与速度","navigationLabel":"规模与速度"},"1":{"title":"类型多样性","navigationLabel":"类型多样性"},"2":{"title":"低价值密度","navigationLabel":"低价值密度"},"3":{"title":"应用不等于单次识别","navigationLabel":"应用不等于单次识别"},"4":{"title":"大数据与普通大文件","navigationLabel":"大数据与普通大文件"},"5":{"title":"采集到应用的处理过程","navigationLabel":"采集到应用的处理过程"},"6":{"title":"V列表与数据质量","navigationLabel":"V列表与数据质量"},"7":{"title":"大数据与其他技术的关系","navigationLabel":"大数据与其他技术的关系"}},"searchAliases":["4V 5V Veracity","大数据处理流程"]},{"q":40,"chapter":9,"section":"9.4","type":"判断","topic":"相关与因果","title":"推荐系统发现相关性不等于证明因果关系","trigger":"题目以购买一本书后收到相似推荐为例考查大数据时代的相关关系。","conclusion":"推荐系统可根据共现、相似用户或行为模式发现相关性，但相关性本身不能证明一个行为导致另一个结果。","points":["协同过滤常利用“相似用户也喜欢”的模式。","混杂因素可能同时影响两个变量。","因果判断通常需要实验设计、自然实验或更严格的统计证据。","大数据场景常重视更广数据范围、及时处理和相关模式，但不意味着必须不用抽样、不求精度或不研究因果；数据规模大也不能自动消除偏差。","2021年第19题用教材式对照概括大数据思维，配套答案并不表示分析应拒绝抽象。具体数据和抽象模型可以配合：交通记录是具体观测，按路段汇总并构建拥堵模型就是抽象；同样不能由数据量大推出无需抽样、精度或因果研究。"],"boundary":"推荐有效只说明相关模式有预测价值，不代表系统已经解释真实原因。","id":"y2025q40","sources":[{"year":2025,"q":40,"type":"判断"},{"year":2021,"q":19,"type":"单选","page":4}],"keys":["2025-40","2021-19"],"related":[{"id":"y2025q18","label":"大数据的规模、速度、多样性与价值密度要按材料判断","reason":"大规模多来源数据提供模式发现的材料，但有用信息占比、样本偏差与因果证据仍须分别判断。"},{"id":"y2020q30","label":"人工智能从感知、学习和推理支持智慧应用","reason":"推荐属于学习、预测等智慧应用的语境；预测有效不等于模型已经说明现实原因。"}],"pointGroups":[{"title":"先分清统计关系与因果解释","indices":[0,1,2]},{"title":"教材概括的适用范围","indices":[3,4]}],"pointPresentation":{"0":{"title":"相关关系","navigationLabel":"相关关系"},"1":{"title":"潜在共同原因","navigationLabel":"潜在共同原因"},"2":{"title":"验证因果需要额外证据","navigationLabel":"验证因果需要额外证据"},"3":{"title":"旧教材口径的边界","navigationLabel":"旧教材口径的边界"},"4":{"title":"具体数据与抽象模型并不排斥","navigationLabel":"具体数据与抽象模型并不排斥"}}},{"q":19,"chapter":9,"section":"9.5","type":"单选","topic":"区块链","title":"区块链结构、共识、可追溯性与信任边界","trigger":"真题从账本结构、多节点共识、难篡改、可追溯和缺少单一信任中心的协作考查区块链。","conclusion":"区块链是以密码学方式连接并由多方共同维护的分布式账本；它可降低多方协作中的部分信任成本，但不消除治理责任。","points":["哈希连接和共识机制使历史记录难以被单方静默篡改。","公有链记录通常较透明，许可链可限制参与和可见范围。","链上输入仍可能错误，隐私、法律和线下履约仍需制度与技术保障。","数字签名使用非对称密码：签名者用私钥签名，接收方用相应公钥验证。哈希摘要本身不等于数字签名；签名用于验证来源与完整性，不等于加密内容保密。","区块保存一批记录及相关元数据，后继区块引用前一区块的密码学哈希（摘要），形成可验证的关联。修改历史记录会改变重新计算的摘要，通常使保存值或后续关联检查不一致；哈希不等于把记录内容加密。","多个参与节点按系统规定验证记录，并通过共识机制协调接受何种账本状态。共识不是“谁都可随意写”；公有链和许可链的参与、写入、读取权限可以不同，也不是所有区块链都使用工作量证明PoW。","可追溯强调能沿保存的记录及关联核查历史，例如一批货物的登记、流转和接收。谁有权查看、链外身份是否属实、最初录入的数据是否真实，仍需其他制度或技术保证。","比特币是区块链的一种典型应用，不等于区块链本身。区块链也可用于多方记录协作；是否值得采用要看参与方、信任关系、性能和治理要求，不是所有数据库都需要改成链。","2026年第20题的配套答案使用公有链的简化特征。具体系统仍须核对准入和可见范围：“去中心化”不意味着没有治理者，“链上记录可核查”也不意味着任何人都能读取全部数据或天然获得隐私保护。"],"boundary":"“难篡改”不等于绝对不可篡改，“去中心化”也不等于完全匿名或无需信任。","id":"merged-17","sources":[{"year":2020,"q":19,"type":"单选"},{"year":2023,"q":40,"type":"判断"},{"year":2024,"q":40,"type":"判断"},{"year":2025,"q":19,"type":"单选"},{"year":2026,"q":20,"type":"单选"}],"keys":["2020-19","2023-40","2024-40","2025-19","2026-20"],"related":[{"id":"merged-15","label":"加密、解密、公钥与私钥","reason":"哈希连接与数字签名承担不同工作，签名需检查私钥、公钥归属及消息完整性，不能与保密加密混同。"},{"id":"y2024q20","label":"沉浸与互操作不会自动消除隐私风险","reason":"公开且难删除的记录会带来隐私治理难题，链上可追溯并不能直接推出用户隐私安全。"}],"pointGroups":[{"title":"结构、验证与共识","indices":[4,5,0,3]},{"title":"应用、追溯与信任边界","indices":[7,6,1,2,8]}],"pointPresentation":{"0":{"title":"篡改与共识验证","navigationLabel":"篡改与共识验证"},"1":{"title":"公有链与许可链","navigationLabel":"公有链与许可链"},"2":{"title":"链上不自动等于真实","navigationLabel":"链上不自动等于真实"},"3":{"title":"数字签名与摘要不同","navigationLabel":"数字签名与摘要不同"},"4":{"title":"区块和摘要关联","navigationLabel":"区块和摘要关联"},"5":{"title":"共识与参与权限","navigationLabel":"共识与参与权限"},"6":{"title":"如何理解可追溯","navigationLabel":"如何理解可追溯"},"7":{"title":"比特币是应用之一","navigationLabel":"比特币是应用之一"},"8":{"title":"公有链简化表述的条件","navigationLabel":"公有链简化表述的条件"}},"searchAliases":["共识机制 PoW","比特币 区块链","不可篡改 可追溯"]},{"q":30,"chapter":9,"section":"9.6","type":"多选","topic":"人工智能应用","title":"人工智能从感知、学习和推理支持智慧应用","trigger":"真题从智慧应用、技术定义和“全面替代人类”等表述考查人工智能。","conclusion":"人工智能通过感知、学习、推理、预测和决策支持语音、人脸、自动驾驶与智慧城市等应用。","points":["智慧城市还会结合物联网、云计算和大数据。","自动化不必然等于人工智能，固定规则也可自动执行。","技术应用要兼顾隐私、安全、公平和人工监督。","计算机视觉、自然语言处理与围棋系统都是人工智能应用方向；“研究目标是完全取代人类”不是人工智能的标准定义。","人工智能AI包含多种技术路线；机器学习ML是利用数据或经验改进任务表现的重要方法，深度学习DL是其中采用多层表示学习的一类方法。三者不是同义词，也不能把所有AI都缩成深度学习。","规则或知识驱动的专家系统也可以属于AI。判断时看其任务与机制，而不是只看是否“自动”：定时开关只是按固定日程动作，专家系统则可结合知识库和推理规则给出判断。","在常见机器学习流程中，先确定任务和数据，训练时根据数据调整模型参数，再在推断时把新输入交给模型得到分类、预测等输出，最后评价错误与适用范围。通常一次普通调用不会重新训练全部参数；数据质量、任务设定和评价同样重要。"],"boundary":"不能只凭“自动运行”或“联网设备多”就判定使用了人工智能。","id":"y2020q30","sources":[{"year":2020,"q":30,"type":"多选"},{"year":2025,"q":39,"type":"判断"},{"year":2021,"q":20,"type":"单选","page":4}],"keys":["2020-30","2025-39","2021-20"],"related":[{"id":"merged-19","label":"物联网的感知、连接与数据处理","reason":"智慧城市可由物联网采集和传输状态，再交给分析与智能服务；联网和自动化本身不足以证明用了AI。"},{"id":"y2025q20","label":"生成式人工智能能辅助多种任务，但输出必须核验","reason":"生成式AI是具体任务方向，可从输入理解、输出生成和事实核验进一步认识其能力边界。"},{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"AI训练和应用依赖算力，但处理能力还受算法、数据与工程实现影响，不能只看芯片指标。"}],"pointGroups":[{"title":"AI的能力和技术层级","indices":[4,3,1,5]},{"title":"从训练到应用","indices":[6,0,2]}],"pointPresentation":{"0":{"title":"智慧城市的技术协作","navigationLabel":"智慧城市的技术协作"},"1":{"title":"自动化的判断条件","navigationLabel":"自动化的判断条件"},"2":{"title":"应用中的责任边界","navigationLabel":"应用中的责任边界"},"3":{"title":"不是全面替代人类","navigationLabel":"不是全面替代人类"},"4":{"title":"AI、机器学习、深度学习","navigationLabel":"AI、机器学习、深度学习"},"5":{"title":"规则系统与自动化","navigationLabel":"规则系统与自动化"},"6":{"title":"训练、推断与评价","navigationLabel":"训练、推断与评价"}},"searchAliases":["机器学习 ML","深度学习 DL","专家系统 训练 推断"]},{"q":30,"chapter":9,"section":"9.6","type":"多选","topic":"生成式人工智能","title":"生成式人工智能能辅助多种任务，但输出必须核验","trigger":"真题从ChatGPT应用、模型可靠性和文字润色考查生成式人工智能。","conclusion":"生成式人工智能学习数据中的模式，并根据提示生成文本、图像、音频等内容，可辅助问答、改写、翻译和编程；生成结果是否正确仍须核验。","points":["理解或识别侧重分析输入，例如判断一句话表达的情绪；生成侧重组织新输出，例如依据要点写一段通知。同一系统可以把理解与生成结合起来完成任务。","模型可能产生事实错误、过时信息、伪造出处或不安全代码。","医学等高风险内容应与权威资料和专业判断交叉验证。","例如给出“周三14点、机房301、携带学生证”三个要点，让模型写通知，再逐项核对日期、地点、要求是否保留。提供素材、明确输出要求、检查结果，可以形成可复查的辅助流程。","根据输入信息组织新的自然语言文字，属于自然语言生成，例如依据要点写通知或按要求改写段落。它与理解、分类任务的关注点不同；生成式AI还可以生成图像、音频或代码，不只限于聊天。","生成式AI是按输出任务划分的方向，不是必须接在AI、ML、DL之后的第四级。改变提示或补充素材会改变当前生成条件，但不等于本次输入一定更新了模型参数；输出流畅也不是事实已经验证。"],"boundary":"模型名称、发布地区或能力范围都不能成为“结果完全可信”的证据。","id":"y2025q20","sources":[{"year":2024,"q":30,"type":"多选"},{"year":2025,"q":20,"type":"单选"},{"year":2025,"q":44,"type":"填空"}],"keys":["2024-30","2025-20","2025-44"],"related":[{"id":"y2026q30","label":"使用AI生成内容要核验、披露并尊重权利","reason":"人工核验之外，公开传播和特定用途还可能需要披露AI参与并尊重著作权与隐私。"},{"id":"y2024q17","label":"信息检索从需求分析到结果评价形成闭环","reason":"核验模型给出的事实或出处时，可按需求分析、资源选择、检索和结果评价的过程寻找外部证据。"}],"pointGroups":[{"title":"理解、生成与具体任务流程","indices":[0,4,3,5]},{"title":"判断输出是否可靠","indices":[1,2]}],"pointPresentation":{"0":{"title":"理解与生成","navigationLabel":"理解与生成"},"1":{"title":"常见输出错误","navigationLabel":"常见输出错误"},"2":{"title":"高风险内容核验","navigationLabel":"高风险内容核验"},"3":{"title":"通知生成与逐项核对","navigationLabel":"通知生成与逐项核对"},"4":{"title":"自然语言生成","navigationLabel":"自然语言生成"},"5":{"title":"提示、参数与事实不同","navigationLabel":"提示、参数与事实不同"}},"searchAliases":["自然语言生成 NLG","生成式AI 技术能力"]},{"q":45,"chapter":9,"section":"9.6","type":"填空","topic":"算力","title":"算力表示计算设备处理数据的能力","trigger":"题目要求填写人工智能和数字技术发展所依赖的重要基础能力。","conclusion":"算力是计算资源执行运算和处理数据的综合能力。","points":["常见指标包括每秒运算次数、吞吐量、延迟和能效。","AI算力不仅取决于芯片，也取决于存储、网络、软件栈和集群调度。","不同任务需要不同精度与体系结构，指标不能简单横比。","CPU适合通用控制及多种计算任务，GPU和专用AI加速器常用于适合其结构的并行计算。能否更快还取决于任务可并行程度、运算精度、内存和数据传输；不能由“用了GPU”推出所有程序都更快。选择设备先看任务，再比较相同条件下的表现。"],"boundary":"算力不是唯一决定因素，算法效率、数据质量和工程实现同样影响结果。","id":"y2026q45","sources":[{"year":2026,"q":45,"type":"填空"}],"keys":["2026-45"],"related":[{"id":"y2026q31","label":"GPU擅长并行计算但不能全面替代CPU","reason":"GPU适合矩阵等并行任务，CPU承担通用控制与协调，可据任务特点理解为何不能只比峰值算力。"},{"id":"y2025q1","label":"字长、主频、核心与指令速度是不同性能指标","reason":"主频、核心数和指令速率反映不同维度，不能简单相加或用单个指标代表整机处理能力。"},{"id":"y2022q33","label":"时间复杂度与空间复杂度不必同向变化","reason":"硬件能力和算法增长趋势是两层问题；提高算力不改变某算法时间、空间复杂度的定义。"}],"pointGroups":[{"title":"能力、指标与约束","indices":[0,2,1]},{"title":"按任务理解硬件选择","indices":[3]}],"pointPresentation":{"0":{"title":"算力相关指标","navigationLabel":"算力相关指标"},"1":{"title":"系统级瓶颈","navigationLabel":"系统级瓶颈"},"2":{"title":"指标的比较条件","navigationLabel":"指标的比较条件"},"3":{"title":"CPU、GPU与AI加速器","navigationLabel":"CPU、GPU与AI加速器"}}},{"id":"syllabus-quantum-basics","chapter":9,"section":"9.7","origin":"syllabus","topic":"考纲补充","title":"量子信息利用量子态编码和处理信息","conclusion":"经典比特通常取0或1；量子比特用量子态表示信息，可以处于叠加态。按计算基进行一次测量只得到0或1中的一个结果，不能把所有可能答案一次读出。","points":["量子计算利用量子态演化和干涉设计算法；纠缠描述多个量子系统之间不能简单拆成各自独立状态的关联。纠缠本身不允许超光速传递可控消息。","量子信息可包括量子计算、量子通信和量子测量等方向。量子计算可能帮助特定问题求解，但不会自动让每一种普通程序都更快，也不能仅凭量子比特数量比较完整性能。","经典bit用0或1编码；qubit用量子态编码，常以|0⟩和|1⟩作为一组基态。叠加态可由这组基态的叠加描述，并不表示测量时可以同时读出两个经典值。","理想例子：每次先重新制备等幅叠加态，再按计算基测量，一次只得到0或1，各有50%的概率；有限次实验不保证恰好各占一半。若第一次测量后不重新制备也不施加其他操作，立即在同一基下再测，会重复得到第一次结果。","量子算法需要准备状态、执行相应操作并利用干涉，最后测量和处理经典结果。纠缠提供量子系统之间的特殊关联资源，但不能让双方自由选择测量结果来瞬间发送信息。","量子密钥分发是量子通信的一类应用，用于建立共享密钥，仍需要认证的经典通信等条件。它不是把任意业务内容瞬间传送，也不能仅凭“量子”保证终端、实现和全部业务绝对安全。","应用与发展要区分目标和能力：量子计算研究特定计算任务，量子通信研究信息传递与安全机制，量子精密测量利用量子效应改进测量。实际收益取决于任务、噪声与实现条件；不以设备宣传中的量子比特数量断言已取代经典计算。"],"boundary":"不要把“叠加”解释为能免费读取全部并行分支，也不要把量子计算与传统CPU主频混为一谈。","sources":[],"trigger":"依据山东省2026年专升本公共基础课考试要求补充；下方为教学示例。","related":[{"id":"y2026q45","label":"算力表示计算设备处理数据的能力","reason":"联系相邻知识理解作用范围"}],"pointGroups":[{"title":"信息如何表示与测量","indices":[2,3]},{"title":"计算、关联与通信","indices":[4,0,5]},{"title":"应用方向与现实边界","indices":[1,6]}],"pointPresentation":{"0":{"title":"演化、干涉与纠缠","navigationLabel":"演化、干涉与纠缠"},"1":{"title":"方向和性能边界","navigationLabel":"方向和性能边界"},"2":{"title":"bit与qubit","navigationLabel":"bit与qubit"},"3":{"title":"重新制备与重复测量","navigationLabel":"重新制备与重复测量"},"4":{"title":"算法到经典结果","navigationLabel":"算法到经典结果"},"5":{"title":"量子密钥分发的条件","navigationLabel":"量子密钥分发的条件"},"6":{"title":"应用方向和实现限制","navigationLabel":"应用方向和实现限制"}},"searchAliases":["量子比特 qubit","叠加态 测量","量子通信 量子精密测量"]},{"q":20,"chapter":9,"section":"9.8","type":"单选","topic":"元宇宙","title":"元宇宙的虚实交互、支撑技术与治理边界","trigger":"题目辨析元宇宙、区块链、虚拟身份与隐私之间的关系。","conclusion":"元宇宙讨论把虚拟与物理世界联系起来的共享数字环境，用户可在其中交互。它不是某一种设备、游戏或区块链产品；沉浸与互操作也不会自动消除隐私风险。","points":["沉浸式设备可能采集视线、动作、空间和生理等高敏感数据。","区块链的公开与难删除特性反而可能放大隐私治理难题。","身份、资产和平台互操作需要标准、权限与责任机制。","理解本体先看环境与参与者：多人通过数字身份在共享数字空间中与对象、服务及他人交互，并可与物理世界活动相联系。ITU-T Y.4238/Y.4239采用共享集体虚拟环境、物理与虚拟世界融合的定义语境；这不规定行业只能采用一种产品或实现。","支撑技术各有分工：VR/AR提供体验与交互，网络和云提供连接与资源，AI可支持识别或生成，数字孪生可建立物理对象的数字对应，分布式记录可用于特定协作。不是每个系统都必须同时使用全部技术，也不以购买头显或采用区块链作为充分条件。","例如远程协作设计可让参与者在共享空间观察和修改数字模型，再核对它与现实对象的对应。能展示三维场景只是部分能力；持续交互、身份权限、数据交换和现实约束仍需实现，不能仅凭“元宇宙”名称认为全部成熟。参与者可用数字化身承担不同角色，场景、模型和互动内容共同支撑体验；切换虚拟角色不意味着摆脱现实责任。","把本章技术联系起来时，按任务组织而非堆热词：物联网取得现实状态，大数据方法组织分析数据，云/HPC提供不同层面的计算支持，AI完成具体智能任务，VR/AR呈现交互。量子信息是另一类信息处理方向；这些技术不会必然全部汇成元宇宙。"],"boundary":"“用了区块链”不等于隐私天然安全；去中心化也不等于没有运营者、规则或治理责任。","id":"y2024q20","sources":[{"year":2024,"q":20,"type":"单选"}],"keys":["2024-20"],"related":[{"id":"merged-18","label":"虚拟现实的核心特征与判断边界","reason":"先分清VR、AR的环境与交互条件，再理解沉浸式设备为何需要采集动作、空间等信息。"},{"id":"merged-17","label":"区块链结构、共识、可追溯性与信任边界","reason":"区块链的公开、可追溯和难删除特征可能放大隐私问题，不能把它当成自动保密机制。"},{"id":"y2020q20","label":"网络行为要尊重权限、署名与责任边界","reason":"数字身份与平台互操作仍受权限、来源和传播责任约束，技术上可互通不表示有权任意使用数据。"}],"pointGroups":[{"title":"先认识共享数字环境","indices":[3,4,5]},{"title":"再检查隐私与互操作","indices":[0,1,2]},{"title":"技术关系与发展判断","indices":[6]}],"pointPresentation":{"0":{"title":"沉浸设备采集的数据","navigationLabel":"沉浸设备采集的数据"},"1":{"title":"链上数据的隐私边界","navigationLabel":"链上数据的隐私边界"},"2":{"title":"互操作需要规则","navigationLabel":"互操作需要规则"},"3":{"title":"元宇宙的本体与定义语境","navigationLabel":"元宇宙的本体与定义语境"},"4":{"title":"支撑技术不等于必备清单","navigationLabel":"支撑技术不等于必备清单"},"5":{"title":"应用例子与成熟度判断","navigationLabel":"应用例子与成熟度判断"},"6":{"title":"八节技术如何协作","navigationLabel":"八节技术如何协作"}},"searchAliases":["元宇宙 metaverse","数字孪生 虚实融合"]}],"sourceCount":460,"years":[2020,2021,2022,2023,2024,2025,2026]};
